class AutoCompleteDialogController{constructor($mdDialog,DispatchData,toastrService,rateJobService,id,fieldName,title,job,options,existingItem,showRerateOption){this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.rateJobService=rateJobService;this.id=id;this.fieldName=fieldName;this.title=title;this.job=job;this.options=options;this.isLoading=false;this.searchText="";this.selectedItem=existingItem;this.showRerateOption=showRerateOption;this.shouldRerateJob=false}async querySearch(searchTerm){try{const url=this.options.searchUrl;return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async submit(selectedItem){this.isLoading=true;try{const reRate=this.shouldRerateJob;const callData={call:"updateDetailField",field:this.fieldName,value:selectedItem.id,jobID:this.job.id};if(reRate&&!this.job.bulkJob){const rate=await this.rateJobService.rateJob(this.job);await this.DispatchData.updateJobDetail(callData.jobID,callData.field,callData.value,Number(rate.replace(/[^0-9.-]+/g,"")),FirstName,ContactID,this.job.preBook)}else{this.job.bulkJob?await this.DispatchData.updateBulkJobDetail(this.job.id,callData.field,callData.value,this.job.charge,FirstName,ContactID):await this.DispatchData.updateJobDetail(callData.jobID,callData.field,callData.value,this.job.charge,FirstName,ContactID)}}catch(error){this.toastrService.showErrorToast()}finally{this.isLoading=false;this.$mdDialog.hide();this.toastrService.showSuccessToast(this.title+" successfully updated to "+selectedItem.text)}}cancel(){this.$mdDialog.cancel()}}